// Estimate the critical density from the sweep and chart the transition.
const fire = nb.get('fire');
if (!fire) return 'Run the Lua cell first.';
const KNOWN = 0.5927;
const s = fire.sweep;

let estimate = null;
for (let k = 1; k < s.length; k++) {
  if (s[k - 1].crossed < 0.5 && s[k].crossed >= 0.5) {
    const a = s[k - 1], b = s[k];
    estimate = a.p + (0.5 - a.crossed) * (b.p - a.p) / (b.crossed - a.crossed);
    break;
  }
}
const longest = s.reduce((best, r) => (r.steps > best.steps ? r : best));
console.log(fire.w + ' x ' + fire.h + ' board, ' + s.length + ' densities');
if (estimate === null) console.log('the crossed share never passed 50% in this sweep');
else console.log('half the fires cross at p = ' + estimate.toFixed(3) + '  (known: ' + KNOWN + ')');
console.log('fires last longest at p = ' + longest.p.toFixed(2) + ': ' + longest.steps.toFixed(1) + ' steps on average');

const shares = s.flatMap(r => [
  { p: r.p, share: r.crossed, measure: 'fires that crossed' },
  { p: r.p, share: r.burned, measure: 'trees burned' },
]);
// vconcat charts can't stretch to the cell's width, so they get a fixed one.
const x = { field: 'p', type: 'quantitative', title: 'tree density p', scale: { domain: [0.4, 0.8] } };
return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  vconcat: [
    {
      width: 700,
      height: 220,
      title: 'The phase transition' + (estimate === null ? '' : ' (50% crossing at ' + estimate.toFixed(3) + ')'),
      layer: [
        {
          data: { values: shares },
          mark: { type: 'line', point: true },
          encoding: {
            x,
            y: { field: 'share', type: 'quantitative', axis: { format: '%' }, title: null },
            color: { field: 'measure', type: 'nominal', title: null },
          },
        },
        {
          data: { values: [{ p: KNOWN }] },
          mark: { type: 'rule', strokeDash: [5, 4], color: '#facc15' },
          encoding: { x: { field: 'p', type: 'quantitative' } },
        },
      ],
    },
    {
      width: 700,
      height: 160,
      title: 'How long the fire lasts',
      data: { values: s },
      mark: { type: 'line', point: true, color: '#f97316' },
      encoding: { x, y: { field: 'steps', type: 'quantitative', title: 'steps' } },
    },
  ],
};
